vulnerable_code_snippet:
if (this.options.sanitize) {
  try {
    var prot = decodeURIComponent(unescape(href))
      .replace(/[^\w:]/g, '')
      .toLowerCase();
  } catch (e) {
    return '';
  }
  if (prot.indexOf('javascript:') === 0) {
    return '';
  }
}

