  !siz->tileheight || !siz->numcomps || siz->numcomps > 16384) {
	return -1;
}
if (siz->tilexoff >= siz->width || siz->tileyoff >= siz->height) {
	jas_eprintf("all tiles are outside the image area\n");
	return -1;
}

