public static function xss_entity_decode($content)
{
    $out = html_entity_decode(html_entity_decode($content));
    $out = strip_tags($out);
    $out = preg_replace_callback('/\\\([0-9a-f]{4})/i',
        array(self, 'xss_entity_decode_callback'), $out);
    $out = preg_replace('#/\*.*\*/#Ums', '', $out);

    return $out;
}

def _wrap_dict(v):
    for k in v.keys():
        if v[k] is not None:
            v[wrap_var(k)] = wrap_var(v[k])
    return v


def _wrap_list(v):
    for idx, item in enumerate(v):
        if item is not None:
            v[idx] = wrap_var(item)
    return v


def wrap_var(v):
    if isinstance(v, dict):
        v = _wrap_dict(v)
    elif isinstance(v, list):
        v = _wrap_list(v)
    else:
        if v is not None and not isinstance(v, AnsibleUnsafe):
            v = UnsafeProxy(v)
    return v

