std::vector<std::vector<std::string> > CSQLHelper::safe_queryBlob(const char *szQuery, ...)
{
	std::vector<std::vector<std::string> > results;
	try
	{
		va_list args;
		va_start(args, szQuery);
		char* zQuery = sqlite3_vmprintf(szQuery, args);
		va_end(args);
		if (!zQuery)
		{
			_log.Log(LOG_ERROR, "SQL: Out of memory, or invalid printf!....");
			std::vector<std::vector<std::string> > results;
			return results;
		}
		results = queryBlob(zQuery);
		sqlite3_free(zQuery);
	}
	catch (const std::exception& e)
	{
		_log.Log(LOG_ERROR, "SQL query error!");
#ifdef _DEBUG
		_log.Log(LOG_ERROR, "-----------------\n%s\n----------------", boost::diagnostic_information(e).c_str());
#else
		(void)e;
#endif
	}
	return results;
}

