public static function validateImage($file)
{
    $fileType = CFileHelper::getMimeType($file['tmp_name']);
    $allowedTypes = array(
        'image/gif',
        'image/jpeg',
        'image/png',
        'image/svg+xml',
    );

    $check = in_array($fileType, $allowedTypes);
    $uploadresult = '';
    if (!$check) {
        $uploadresult = gT('This file is not a supported image - please only upload JPG,PNG,GIF or SVG type');
    }

    return array('check' => $check, 'uploadresult' => $uploadresult);
}

function wp_kses_bad_protocol_once( $string, $allowed_protocols, $count = 1 ) {
	$string2 = preg_split( '/:|&#0*58;|&#x0*3a;/i', $string, 2 );
	if ( isset( $string2[1] ) && ! preg_match( '%/\?%', $string2[0] ) ) {
		$string   = trim( $string2[1] );
		$protocol = wp_kses_bad_protocol_once2( $string2[0], $allowed_protocols );
		if ( 'feed:' == $protocol ) {
			if ( $count > 2 ) {
				return '';
			}
			$string = wp_kses_bad_protocol_once( $string, $allowed_protocols, ++$count );
			if ( empty( $string ) ) {
				return $string;
			}
		}
		$string = $protocol . $string;
	}

	return $string;
}

def file_method?(attribute_name)
  file = @object.send(attribute_name) if @object.respond_to?(attribute_name)
  file && SimpleForm.file_methods.any? { |m| file.respond_to?(m) }
end

