GIT_INLINE(bool) verify_dotgit_ntfs(git_repository *repo, const char *path, size_t len)
{
	git_buf *reserved = git_repository__reserved_names_win32;
	size_t reserved_len = git_repository__reserved_names_win32_len;
	size_t start = 0, i;

	if (repo)
		git_repository__reserved_names(&reserved, &reserved_len, repo, true);

	for (i = 0; i < reserved_len; i++) {
		git_buf *r = &reserved[i];

		if (len >= r->size &&
			strncasecmp(path, r->ptr, r->size) == 0) {
			start = r->size;
			break;
		}
	}

	if (!start)
		return true;

	/* Reject paths like ".git\" */
	if (path[start] == '\\')
		return false;

	/* Reject paths like '.git ' or '.git.' */
	for (i = start; i < len; i++) {
		if (path[i] != ' ' && path[i] != '.')
			return true;
	}

	return false;
}

public static function sanitizeUrl(string $url, bool $checkStatus = true): string
{
    $url = UrlHelper::stripQueryString($url);
    // HTML decode the entities, then strip out any tags
    $url = html_entity_decode($url, ENT_NOQUOTES, 'UTF-8');
    $url = strip_tags($url);

    // If this is a >= 400 status code, set the canonical URL to nothing
    if ($checkStatus && Craft::$app->getResponse()->getStatusCode() >= 400) {
        $url = '';
    }

    return $url;
}

