vulnerable_code_snippet:
function jqMix(obj, props){
    if(obj == props){
        return obj;
    }
    var tobj = {};
    for(var x in props){
        // the "tobj" condition avoid copying properties in "props"
        // inherited from Object.prototype.  For example, if obj has a custom
        // toString() method, don't overwrite it with the toString() method
        // that props inherited from Object.prototype
        if((tobj[x] === undefined || tobj[x] != props[x]) && props[x] !== undefined && obj != props[x]){
            if(dojo.isObject(obj[x]) && dojo.isObject(props[x])){
                if(dojo.isArray(props[x])){
                    obj[x] = props[x];
                }else{
                    obj[x] = jqMix(obj[x], props[x]);
                }
            }else{
                obj[x] = props[x];
            }
        }
    }
    if(dojo.isIE && props){
        var p = props.toString;
        if(typeof p == "function" && p != obj.toString && p != tobj.toString &&
            p != "\nfunction toString() {\n    [native code]\n}\n"){
            obj.toString = props.toString;
        }
    }
    return obj;
}

if (opt.innerHTML && opt.dompurify) {
  el.innerHTML = opt.dompurify.sanitize(opt.innerHTML);
}

function sanitizeShellString(str) {
  const s = str || '';
  let result = '';
  for (let i = 0; i <= 2000; i++) {
    if (!(s[i] === undefined ||
      s[i] === '>' ||
      s[i] === '<' ||
      s[i] === '*' ||
      s[i] === '?' ||
      s[i] === '[' ||
      s[i] === ']' ||
      s[i] === '|' ||
      s[i] === '˚' ||
      s[i] === ';' ||
      s[i] === '&' ||
      s[i] === '\t' ||
      s[i] === '\n')) {
      result = result + s[i];
    }
  }
  return result;
}

