     }
 }
 if ($ok) {

vulnerable_code_snippet:
if ($ok) {
    $uris = array_map("trim", explode("\n", $config->lti_redirectionuris));
    $ok = in_array($redirecturi, $uris);
    if (!$ok) {
        $error = 'invalid_request';
        $desc = 'Unregistered redirect_uri ' . $redirecturi;
    }
}

