const urlParts = (req.url || '').split('?')
const urlNoQuery = urlParts[0]

if (urlNoQuery?.match(/(\\|\/\/)/)) {
  const cleanUrl = normalizeRepeatedSlashes(req.url!)
  res.setHeader('Location', cleanUrl)
  res.setHeader('Refresh', `0;url=${cleanUrl}`)
  res.statusCode = 308
  res.end(cleanUrl)
  return
}

