public function itemToString($item, string $indent, string $escapeStart, string $escapeEnd): string
{
    $attrString = '';
    if (!empty($item->attributes)) {
        foreach ($item->attributes as $key => $value) {
            if (!$this->arbitraryAttributesAllowed()
                && !in_array($key, $this->optionalAttributes)) {
                continue;
            }

            if ('defer' == $key) {
                $value = 'defer';
            }

            $attrString .= sprintf(' %s="%s"', $key, $this->isAutoEscape() ? $this->escape($value) : $value);
        }
    }

    $type = $this->isAutoEscape() ? $this->escape($item->type) : $item->type;
    $html = $indent . '<script type="' . $type . '"' . $attrString . '>';
    if (!empty($item->source)) {
        $html .= PHP_EOL . $indent . '    ' . (empty($item->attributes['noescape']) ? $escapeStart : '') . PHP_EOL . $item->source . $indent . '    ' . (empty($item->attributes['noescape']) ? $escapeEnd : '') . PHP_EOL . $indent;
    }
    $html .= '</script>';

    if (isset($item->attributes['conditional'])
        && !empty($item->attributes['conditional'])
        && is_string($item->attributes['conditional'])) {
        $html = '<!--[if ' . $item->attributes['conditional'] . ']> ' . $html . '<![endif]-->';
    }

    return $html;
}

public function isDangerFilename($filename){

	$isDangerStr = function ($filename , $keyword){
		if(strstr(strip_tags(strtolower( $filename )), $keyword) ){
			return true ;
		}
		return false;
	};
	if (
		$isDangerStr($filename , ".php")
		|| $isDangerStr($filename , ".svg")
		|| $isDangerStr($filename , ".htm")
		|| $isDangerStr($filename , "%")
	) {
		return true;
	}

	return false;
}

