enum HtmlEscaper implements Escaper {

	Html;

	private static final String QUOT = "&quot;";

	private static final String GT = "&gt;";

	private static final String LT = "&lt;";

	private static final String AMP = "&amp;";

	@Override
	public <A extends Output<E>, E extends Exception> void append(A a, CharSequence s) throws E {
		s = s == null ? "null" : s;
		append(a, s, 0, s.length());
	}

	@Override
	public <A extends Output<E>, E extends Exception> void append(A a, CharSequence csq, int start, int end)
			throws E {
		for (int i = start; i < end; i++) {
			char c = csq.charAt(i);
			switch (c) {
				case '&' -> {
					a.append(csq, start, i);
					start = i + 1;
					a.append(AMP);

				}
				case '<' -> {
					a.append(csq, start, i);
					start = i + 1;
					a.append(LT);

				}
				case '>' -> {
					a.append(csq, start, i);
					start = i + 1;
					a.append(GT);
				}
				case '"' -> {
					a.append(csq, start, i);
					start = i + 1;
					a.append(QUOT);
				}

			}
		}
		a.append(csq, start, end);
	}

	@Override
	public <A extends Output<E>, E extends Exception> void append(A a, char c) throws E {
		switch (c) {
			case '&' -> {
				a.append(AMP);
			}
			case '<' -> {
				a.append(LT);
			}
			case '>' -> {
				a.append(GT);
			}
			case '"' -> {
				a.append(QUOT);
			}
			default -> {
				a.append(c);
			}
		}
	}

}

def deny_uploads_containing_script_tag(uploaded_file):
    for chunk in uploaded_file.chunks(2048):
        if chunk.lower().find(b"<script") > -1:
            raise ValidationError(_("File contains forbidden <script> tag"))

function filterFilter(Environment $env, $array, $arrow)
{
    if (is_string($arrow) && Utils::isDangerousFunction($arrow)) {
        throw new RuntimeError('Twig |filter("' . $arrow . '") is not allowed.');
    }

    return twig_array_filter($env, $array, $arrow);
}

