public static function normalizePath($path, $ds = DIRECTORY_SEPARATOR)
{
    // Is this a UNC network share path?
    $isUnc = (strpos($path, '//') === 0 || strpos($path, '\\\\') === 0);

    // Normalize the path
    $path = parent::normalizePath($path, $ds);

    // If it is UNC, add those slashes back in front
    if ($isUnc) {
        $path = $ds . $ds . ltrim($path, $ds);
    }

    return $path;
}

@classmethod
def check_unsafe_options(cls, options: List[str], unsafe_options: List[str]) -> None:
    """
    Check for unsafe options.
    Some options that are passed to `git <command>` can be used to execute
    arbitrary commands, this are blocked by default.
    """
    # Options can be of the form `foo` or `--foo bar` `--foo=bar`,
    # so we need to check if they start with "--foo" or if they are equal to "foo".
    bare_unsafe_options = [
        option.lstrip("-")
        for option in unsafe_options
    ]
    for option in options:
        for unsafe_option, bare_option in zip(unsafe_options, bare_unsafe_options):
            if option.startswith(unsafe_option) or option == bare_option:
                raise UnsafeOptionError(
                    f"{unsafe_option} is not allowed, use `allow_unsafe_options=True` to allow it."
                )

def compat_shlex_quote(s):
    import re
    return s if re.match(r'^[-_\w./]+$', s) else '"%s"' % s.replace('"', '\\"')

if contentType == "" {
	disposition = "attachment"
} else {
	if util.HasAnyPrefix(contentType, []string{"image/", "audio/", "video/", "text/plain"}) {
		disposition = "inline"
	} else {
		disposition = "attachment"
	}
}

