public function extensionIsNotExcutable($excutable_extensions)
{
    $extension = strtolower($this->file->getClientOriginalExtension());

    if (in_array($extension, $excutable_extensions)) {
        throw new ExcutableFileException();
    }

    return $this;
}

public function setUrl(string $url): static
{
    $url = trim($url);

    $unsupportedProtocols = ['file://', 'file:/', 'file:\\', 'file:\\\\'];

    foreach ($unsupportedProtocols as $unsupportedProtocol) {
        if (str_starts_with(strtolower($url), $unsupportedProtocol)) {
            throw FileUrlNotAllowed::make();
        }
    }

    $this->url = $url;

    return $this;
}

