+    {
+        $node = new Node();
+
+        $this->assertNull($node->getFirstChildValue());
+
+        $node->children[] = (new Node())->setValue('v1');
+        $node->children[] = (new Node())->setValue('v2');
+
+        $this->assertSame('v1', $node->getFirstChildValue());
+    }
+}

