const escapeDictionary = {
  '"': "&quot;",
  "'": "&apos;",
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
};

const escapeRegExp = new RegExp(
  `[${Object.keys(escapeDictionary).join("")}]`,
  "g",
);

const escapeFunction = (string) => {
  let escaped = "";
  let start = 0;
  let end = 0;

  do {
    const escapedCharacter = escapeDictionary[string[end++]];
    if (escapedCharacter) {
      escaped += string.slice(start, end - 1) + escapedCharacter;
      start = end;
    }
  } while (end < string.length);

  return escaped + string.slice(start, end);
};

private static function attribute_value($node, $attr_name, $attr_value)
{
    $attr_name = strtolower($attr_name);

    foreach ($node->attributes as $name => $attr) {
        if (strtolower($name) === $attr_name) {
            if (strtolower($attr_value) === strtolower($attr->nodeValue)) {
                return true;
            }
        }
    }

    return false;
}

