protected function clean_param_value_localurl(mixed $param): string {
    global $CFG;

    // Allow http absolute, root relative and relative URLs within wwwroot.
    $param = clean_param($param, PARAM_URL);
    if (!empty($param)) {
        if ($param === $CFG->wwwroot) {
            // Exact match.
        } else if (preg_match(':^/:', $param)) {
            // Root-relative, ok!
        } else if (preg_match('/^' . preg_quote($CFG->wwwroot . '/', '/') . '/i', $param)) {
            // Absolute, and matches our wwwroot.
        } else {
            // Relative - let's make sure there are no tricks.
            if (validateUrlSyntax('/' . $param, 's-u-P-a-p-f+q?r?') && !preg_match('/javascript:/i', $param)) {
                // Looks ok.
            } else {
                $param = '';
            }
        }
    }
    return $param;
}

if !strings.HasPrefix(path, "/") {
	// Disambiguate that it's a path relative to this server
	path = fmt.Sprintf("/%s", path)
} else {
	// A string starting with // or /\ is interpreted by browsers as a URL, and not a server relative path
	rePrefix := regexp.MustCompile(`^(?:/\\|/+)`)
	path = rePrefix.ReplaceAllString(path, "/")
}

