func sanitizeSQLExp(q string) string {
	if len(q) == 0 {
		return ""
	}

	// Remove semicolon suffix.
	q = strings.TrimSpace(q)
	if q[len(q)-1] == ';' {
		q = q[:len(q)-1]
	}
	return q
}

