From bc4fdbaeb1dff127fb6d08c0d385b64aa128c8f8 Mon Sep 17 00:00:00 2001
From: SomeRandomDeveloper <thisisnotmyname275@gmail.com>
Date: Thu, 3 Jul 2025 13:30:48 -0400
Subject: [PATCH] fix(SECURITY): escape short description in the subtitle

`mw.util.addSubtitle()` takes raw HTML,
and the description is not sanitized up to this point.
This fixes a stored XSS vulnerability through wikitext.

CVE-2025-53369
---
 modules/ext.shortDescription.js | 2 +-
 1 file changed, 1 insertion(+), 1 deletion(-)

diff --git a/modules/ext.shortDescription.js b/modules/ext.shortDescription.js
index cf00c86..3a91e85 100644
--- a/modules/ext.shortDescription.js
+++ b/modules/ext.shortDescription.js
@@ -5,7 +5,7 @@ function main() {
 		return;
 	}

-	mw.util.addSubtitle( shortdesc );
+	mw.util.addSubtitle( mw.html.escape( shortdesc ) );
 }

 main();

vulnerable_code_snippet:
public function sanitize( $shortDesc ) {
	// Remove accidental formatting - descriptions are plaintext.
	$shortDesc = strip_tags( $shortDesc );
	// Unescape - clients are not necessarily HTML-based and using HTML tags as part of
	// the descript (i.e. with <nowiki> or such) should be possible.
	$shortDesc = html_entity_decode( $shortDesc, ENT_QUOTES, 'utf-8' );

	// Remove newlines, tabs and other weird whitespace
	$shortDesc = preg_replace( '/\s+/', ' ', $shortDesc );

	// Get rid of leading/trailing space - no valid usecase for it, easy for it to go unnoticed
	// in HTML, and clients might display the description in an environment that does not
	// ignore spaces like HTML does.
	return trim( $shortDesc );
}

if IsSymlink(info) {
	resolved, err := filepath.EvalSymlinks(path)
	if err != nil {
		return fmt.Errorf("error evaluating symlink %s: %w", path, err)
	}
	// This log message is to highlight a symlink that is being used within a chart,
	// symlinks can be used for nefarious reasons.
	slog.Info("found symbolic link in path. Contents of linked file included and used", "path", path, "resolved", resolved)
	if info, err = os.Lstat(resolved); err != nil {
		return err
	}
	if err := symwalk(path, info, walkFn); err != nil && err != filepath.SkipDir {
		return err
	}
	return nil
}

