def _reject_unpermitted_characters(headers: Iterable[Header],
                                   hdr_validation_flags: HeaderValidationFlags) -> Generator[Header, None, None]:
    """
    Raises a ProtocolError if any header names or values contain unpermitted characters.
    See RFC 7540, section 10.3 and 8.1.2.6.
    """
    for header in headers:
        for c in HEADER_UNPERMITTED_CHARACTERS:
            if c in header[0]:
                msg = f"Unpermitted character '{c}' in header name: {header[0]!r}"
                raise ProtocolError(msg)
            if c in header[1]:
                msg = f"Unpermitted character '{c}' in header value: {header[1]!r}"
                raise ProtocolError(msg)
        yield header

private static function checkArrowFunction(mixed $arrow, string $thing, string $type): void
{
    if (
        is_string($arrow) &&
        in_array(ltrim(strtolower($arrow), '\\'), [
            'system',
            'passthru',
            'exec',
            'file_get_contents',
            'file_put_contents',
            'popen',
        ])
    ) {
        throw new RuntimeError(sprintf('The "%s" %s does not support passing "%s".', $thing, $type, $arrow));
    }
}

public String encodeCharacter( char[] immune, Character c ) {
    char ch = c.charValue();

    // check for immune characters
    if ( containsCharacter( ch, immune ) ) {
        return ""+ch;
    }

    // check for alphanumeric characters
    String hex = Codec.getHexForNonAlphanumeric( ch );
    if ( hex == null ) {
        return ""+ch;
    }

    switch( mode ) {
        case ANSI: return encodeCharacterANSI( c );
        case STANDARD: return encodeCharacterMySQL( c );
    }
    return null;
}

private String encodeCharacterANSI( Character c ) {
    if ( c == '\'' )
        return "\'\'";
    return ""+c;
}

private String encodeCharacterMySQL( Character c ) {
    char ch = c.charValue();
    if ( ch == 0x00 ) return "\\0";
    if ( ch == 0x08 ) return "\\b";
    if ( ch == 0x09 ) return "\\t";
    if ( ch == 0x0a ) return "\\n";
    if ( ch == 0x0d ) return "\\r";
    if ( ch == 0x1a ) return "\\Z";
    if ( ch == 0x22 ) return "\\\"";
    if ( ch == 0x25 ) return "\\%";
    if ( ch == 0x27 ) return "\\'";
    if ( ch == 0x5c ) return "\\\\";
    if ( ch == 0x5f ) return "\\_";
    return "\\" + c;
}

